import{_ as l,a0 as n,w as r,s as p,ao as d,I as o,x as t,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"IceWM：一个非常酷的桌面 | LCTT x X-CMD","titleTemplate":false,"description":"IceWM：一个非常酷的桌面 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"IceWM：一个非常酷的桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"IceWM：一个非常酷的桌面 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191007 IceWM - A really cool desktop","title":"IceWM：一个非常酷的桌面","tag":"201910","desc":""},"relativePath":"201910/20191007 IceWM - A really cool desktop.md","filePath":"[post].md"}'),c={name:"201910/20191007 IceWM - A really cool desktop.md"};function h(m,e,g,u,f,k){const a=n("Link");return r(),p("div",null,[e[15]||(e[15]=d('<h1 id="icewm-一个非常酷的桌面" tabindex="-1">IceWM：一个非常酷的桌面 <a class="header-anchor" href="#icewm-一个非常酷的桌面" aria-label="Permalink to “IceWM：一个非常酷的桌面”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/09/icewm-1-816x346.png" alt=""></p><p>IceWM 是一款非常轻量的桌面。它已经出现 20 多年了，它今天的目标仍然与当时相同：速度、简单性以及不妨碍用户。</p><p>我曾经将 IceWM 添加到 Scientific Linux 中作为轻量级桌面。当时它只是 0.5 兆的 rpm 包。运行时，它仅使用 5 兆的内存。这些年来，IceWM 有所增长。rpm 包现在为 1 兆。运行时，IceWM 现在使用 10 兆的内存。尽管在过去十年中它的大小增加了一倍，但它仍然非常小。</p><p>这么小的包，你能得到什么？确切地说，就是一个窗口管理器。没有其他东西。你有一个带有菜单或图标的工具栏来启动程序。速度很快。最后，还有主题和选项。除了工具栏中的一些小东西，就只有这些了。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/09/icewm.2-1024x768.png" alt=""></p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>因为 IceWM 很小，你只需安装主软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install icewm</span></span></code></pre></div><p>如果要节省磁盘空间，许多依赖项都是可选的。没有它们，IceWM 也可以正常工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install icewm --setopt install_weak_deps=false</span></span></code></pre></div><h3 id="选项" tabindex="-1">选项 <a class="header-anchor" href="#选项" aria-label="Permalink to “选项”">​</a></h3><p>IceWM 默认已经设置完毕，以使普通的 Windows 用户也能感到舒适。这是一件好事，因为选项是通过配置文件手动完成的。</p><p>我希望你不会因此而止步，因为它并没有听起来那么糟糕。它只有 8 个配置文件，大多数人只使用其中几个。主要的三个配置文件是 <code>keys</code>（键绑定），<code>preferences</code>（总体首选项）和 <code>toolbar</code>（工具栏上显示的内容）。默认配置文件位于 <code>/usr/share/icewm/</code>。</p><p>要进行更改，请将默认配置复制到 IceWM 家目录（<code>~/.icewm</code>），编辑文件，然后重新启动 IceWM。第一次做可能会有点害怕，因为在 “Logout” 菜单项下可以找到 “Restart Icewm”。但是，当你重启 IceWM 时，你只会看到闪烁一下，更改就生效了。任何打开的程序均不受影响，并保持原样。</p><h3 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to “主题”">​</a></h3><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/09/icewm.3-1024x771.png" alt="IceWM in the NanoBlue theme"></p><p>如果安装 icewm-themes 包，那么会得到很多主题。与常规选项不同，你无需重启 IceWM 即可更改为新主题。通常我不会谈论主题，但是由于其他功能很少，因此我想提下。</p><h3 id="工具栏" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏" aria-label="Permalink to “工具栏”">​</a></h3><p>工具栏是为 IceWM 添加了更多的功能的地方。你可以看到它可以切换不同的工作区。工作区有时称为虚拟桌面。单击工作区图标以移动到它。右键单击一个窗口的任务栏项目，可以在工作区之间移动它。如果你喜欢工作区，它拥有你想要的所有功能。如果你不喜欢工作区，那么可以选择关闭它。</p><p>工具栏还有网络/内存/CPU 监控图。将鼠标悬停在图标上可获得详细信息。单击图标可以打开一个拥有完整监控功能的窗口。这些小图形曾经出现在每个窗口管理器上。但是，随着桌面环境的成熟，它们都将这些图形去除了。我很高兴 IceWM 留下了这个不错的功能。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如果你想要轻量但功能强大的桌面，IceWM 适合你。它已经设置好了，因此新的 Linux 用户也可以立即使用它。它是灵活的，因此 Unix 用户可以根据自己的喜好进行调整。最重要的是，IceWM 可以让你的程序不受阻碍地运行。</p><hr>',24)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),s(a,{href:"https://fedoramagazine.org/icewm-a-really-cool-desktop/"},{default:i(()=>[...e[0]||(e[0]=[t("https://fedoramagazine.org/icewm-a-really-cool-desktop/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),s(a,{href:"https://fedoramagazine.org/author/tdawson/"},{default:i(()=>[...e[2]||(e[2]=[t("tdawson",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),s(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),s(a,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),s(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const W=l(c,[["render",h]]);export{M as __pageData,W as default};
